def canon(x):return json.dumps(x,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode('utf-8')
def sha(x):return hashlib.sha256(x).hexdigest()
def read(p):return json.loads(p.read_bytes())
def save(p,x):p.write_bytes((json.dumps(x,ensure_ascii=False,indent=2)+'\n').encode())
def rel(p):return str(p.relative_to(R))
catalog=read(R/'src/content/topics/maps-cartography.json');cards=catalog['questions']; scope=cards[70:77]
author=read(B/'author/candidate.json'); sourceproof=read(B/'author/sourceproof.json')
sources={x['id']:dict(x) for x in sourceproof['sourceRegister']}
for s in sources.values():
 raw=(R/s['path']).read_bytes();s['actualByteSHA256']=sha(raw);s['hashMatchesRegister']=s['actualByteSHA256']==s['sha256'];s['actualBytes']=len(raw)
 assert s['hashMatchesRegister']
def ref(id,locator,claim,ground):
 s=sources[id];return {'primaryPath':s['path'],'primaryByteSHA256':s['actualByteSHA256'],'url':s['url'],'locator':locator,'claim':claim,'actualGround':ground}
