gno=lambda claim,ground:ref('gnomonic','Description; Distortion; Variants; Limitations (complete saved page)',claim,ground)
stere=lambda claim,ground:ref('stereographic','Description; Distortion; Variants A/B/C/auxiliary sphere; Limitations (complete saved page)',claim,ground)
poly=lambda loc,claim,ground:ref('polygon',loc,claim,ground)
line=lambda loc,claim,ground:ref('polyline',loc,claim,ground)
usgs=lambda claim,ground:ref('usgs','PDF p.1 Reading Topographic Maps; p.2 CONTOURS',claim,ground)
os=lambda loc,claim,ground:ref('os',loc,claim,ground)
